export function clamp(x, lo, hi) {
  if (lo > hi) throw new RangeError(`clamp: lo (${lo}) > hi (${hi})`);
  return Math.min(Math.max(x, lo), hi);
}
import assert from "node:assert/strict";
import { test } from "node:test";
import { clamp } from "../src/clamp.mjs";

test("inside range returns x", () => assert.equal(clamp(3, 1, 7), 3));
test("below range returns lo", () => assert.equal(clamp(-5, 1, 7), 1));
test("above range returns hi", () => assert.equal(clamp(99, 1, 7), 7));
test("bounds are inclusive", () => {
  assert.equal(clamp(1, 1, 7), 1);
  assert.equal(clamp(7, 1, 7), 7);
});
test("equal bounds", () => assert.equal(clamp(10, 4, 4), 4));
test("lo > hi throws RangeError", () => assert.throws(() => clamp(0, 2, 1), RangeError));
